from rest_framework import viewsets, permissions
from .models import ExecutiveCompensation
from .serializers import ExecutiveCompensationSerializer

class IsExecutiveOrBoardAdmin(permissions.BasePermission):
    def has_object_permission(self, request, view, obj):
        # Both read and write operations must be restricted to the executive or board admin
        is_owner = obj.executive_user == request.user
        is_board_member = request.user.groups.filter(name="BoardOfDirectors").exists()
        return is_owner or is_board_member

class ExecutiveCompensationViewSet(viewsets.ModelViewSet):
    serializer_class = ExecutiveCompensationSerializer
    permission_classes = [permissions.IsAuthenticated, IsExecutiveOrBoardAdmin]

    def get_queryset(self):
        if self.request.user.groups.filter(name="BoardOfDirectors").exists():
            return ExecutiveCompensation.objects.all()
        return ExecutiveCompensation.objects.filter(executive_user=self.request.user)
